from pathlib import Path
root=Path(__file__).resolve().parents[2]
checks=[]
def txt(path): return (root/path).read_text(encoding='utf-8')
def check(label, cond): checks.append((label,bool(cond)))

designer=txt('frontend/src/grammar-designer/GrammarDesigner.tsx')
monaco=txt('frontend/src/grammar-designer/GrammarMonacoEditor.tsx')
ranges=txt('frontend/src/grammar-designer/grammarTextRange.ts')
range_tests=txt('frontend/src/grammar-designer/grammarTextRange.test.ts')
custom_ui=txt('frontend/src/grammar-designer/GrammarTextualCustomization.tsx')
custom=txt('frontend/src/grammar-designer/textualCustomization.ts')
custom_tests=txt('frontend/src/grammar-designer/textualCustomization.test.ts')
css=txt('frontend/src/grammar-designer/grammar-designer.css')
compilation=txt('frontend/src/grammar-designer/GrammarCompilationPanel.tsx')
core=txt('src/main/java/com/example/editor/grammar/core/GrammarTextualEditorCustomization.java')
core_tests=txt('src/test/java/com/example/editor/grammar/core/GrammarTextualEditorCustomizationTests.java')
visual=txt('src/main/java/com/example/editor/integration/compiler/TechnologyAdapterVisualFullStackSupport.java')
visual_tests=txt('src/test/java/com/example/editor/integration/compiler/TechnologyAdapterVisualFullStackSupportTests.java')
support=txt('src/main/java/com/example/editor/integration/compiler/TechnologyAdapterTextualCustomizationSupport.java')
stand=txt('src/main/resources/standalone-template/frontend/textual-app.js')
vscode_tests=txt('src/test/java/com/example/editor/integration/adapter/vscode/VsCodeExtensionTechnologyAdapterTests.java')
i18n=txt('frontend/src/i18n/grammarSpanishCatalog.ts')

check('visual full-stack decodes byte content explicitly as strict UTF-8', 'StandardCharsets.UTF_8.newDecoder()' in visual and 'CodingErrorAction.REPORT' in visual and 'Visual editor definition must be valid UTF-8' in visual)
check('UTF-8 byte regressions are permanent', 'decodesCanonicalVisualDefinitionBytesAsUtf8' in visual_tests and 'rejectsMalformedUtf8BeforeGeneratingHostSources' in visual_tests)
check('manual source edits invalidate stale navigation focus', 'setFocusDiagnostic(null);mutate(' in designer)
check('grammar navigation ranges are clamped before selection', 'clampTextRange(value,focusRange)' in monaco and 'clampedPositionToOffset' in monaco)
check('fallback navigation leaves a caret instead of selecting a grammar element', 'setSelectionRange(start,start)' in monaco and 'setSelectionRange(start,end)' not in monaco)
check('range utility handles empty and CRLF documents', 'clampedPositionToOffset' in ranges and "code===13" in ranges and "code===10" in ranges)
check('range safety has permanent regression tests', 'clamps stale positions after destructive edits' in range_tests and 'handles empty and CRLF documents without throwing' in range_tests)
check('font is selected from supported presets', 'const FONT_OPTIONS=' in custom_ui and '<select value={customization.fontFamily}' in custom_ui and 'JetBrains Mono' in custom_ui and 'Fira Code' in custom_ui)
check('appearance supports general rule and terminal scopes', "type StyleScope='GENERAL'|'RULE'|'TERMINAL'" in custom_ui and "Specific parser rule" in custom_ui and "Specific terminal" in custom_ui)
check('specific rule and terminal style settings are neutral and bounded', 'symbolStyles' in core and 'MAX_SYMBOL_STYLES = 256' in core and 'SYMBOL_KINDS = Set.of("RULE", "TERMINAL")' in core)
check('frontend specific styles round-trip and normalize TOKEN to TERMINAL', 'symbolStyleKey' in custom and "value==='TERMINAL'||value==='TOKEN'?'TERMINAL'" in custom and 'normalizes legacy TOKEN overrides' in custom_tests)
check('Java specific styles have sanitization and round-trip regressions', 'RULE:Person' in core_tests and 'TERMINAL:ID' in core_tests and 'doesNotContainKeys("SCRIPT:bad","RULE:bad key!")' in core_tests)
check('standalone editor consumes symbol-specific styles', 'hydra.textual.symbol.' in stand and 'specificStyle(c,token)' in stand and 'c.symbols[first]' in stand)
check('VS Code generated runtime consumes symbol-specific styles', 'SYMBOL_STYLES:Record<string,string>' in support and 'symbolDecorations' in support and 'specificKey(role:string,value:string)' in support)
check('VS Code regression fixture carries rule and terminal overrides', 'RULE:Person' in vscode_tests and 'TERMINAL:ID' in vscode_tests)
check('grammar toolbar remains a single line with horizontal overflow fallback', 'flex-wrap:nowrap' in css and 'overflow-x:auto' in css and 'white-space:nowrap' in css)
check('contextual information form uses bounded two-column layout and preview card', 'grammar-hover-fields' in custom_ui and 'grammar-hover-preview' in custom_ui and 'maxLength={600}' in custom_ui and 'grid-template-columns:minmax(320px,720px) minmax(220px,340px)' in css)
check('appearance form uses compact cards and bounded field widths', 'grammar-customization-card' in custom_ui and 'grammar-font-field' in custom_ui and 'max-width:320px' in css and 'max-width:820px' in css)
check('compilation results use status cards with secondary duration metadata', 'grammar-compilation-stage-card' in compilation and '<time>{stage.durationMillis} ms</time>' in compilation)
check('project download action is pill-shaped and carries a download icon', 'grammar-download-project' in compilation and 'grammar-download-project-icon' in compilation and "aria-hidden=\"true\">↓" in compilation and 'border-radius:999px' in css)
check('new UX strings have Spanish coverage', all(token in i18n for token in ["'General editor style'", "'Specific parser rule'", "'Specific terminal'", "'Verified'", "'Not required'"]))
check('new grammar customization CSS introduces no important overrides', all('!important' not in line for line in css.splitlines()[760:]))

failed=[label for label,value in checks if not value]
for label,value in checks: print(('PASS' if value else 'FAIL')+' - '+label)
print(f'V43315_GRAMMAR_TEXT_EDITING_CUSTOMIZATION_UX={len(checks)-len(failed)}/{len(checks)}')
raise SystemExit(1 if failed else 0)
